fn same_order(outcomes: &[Outcome], paths: &[PathBuf]) -> bool {
    outcomes
        .iter()
        .map(|o| o.status_path.as_str())
        .eq(paths.iter().map(|p| p.to_string_lossy()).collect::<Vec<_>>().iter().map(|p| p.as_ref()))
}
